import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Handl Compile Plugin Architecture","description":"","frontmatter":{"title":"Handl Compile Plugin Architecture","type":"adr","date":"2026-09-14T00:00:00.000Z","status":"proposed","status_note":"Accepted — compilers are per-target plugins over one `Compiler` trait."},"headers":[],"relativePath":"handl/project/adrs/0114-handl-compile-plugin-architecture.md","filePath":"vendored/handl/project/adrs/0114-handl-compile-plugin-architecture.md"}'),a={name:`handl/project/adrs/0114-handl-compile-plugin-architecture.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0114-handl-compile-plugin-architecture" tabindex="-1">ADR-0114: Handl Compile Plugin Architecture <a class="header-anchor" href="#adr-0114-handl-compile-plugin-architecture" aria-label="Permalink to “ADR-0114: Handl Compile Plugin Architecture”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>A <code>plugin-compile</code> crate defines <code>Compiler</code> and <code>CompilerInput</code></strong> (a parsed, type-checked <code>Ast</code> plus optional metadata); per-target crates implement it (<code>plugin-compile-js</code>, <code>plugin-compile-llvm</code>).</li><li><strong><code>handl-emitters</code> keeps its role</strong> — emitting <code>Language</code> data fragments; it is not a source-to-source compiler.</li><li><strong><code>hnl compile &lt;target&gt; &lt;file&gt;</code> dispatches by target name</strong>, not file extension; the target triple/runtime is part of the compiler configuration.</li><li><strong>The JS target exposes</strong> <code>compile_to_string</code>, <code>emit_module</code> and <code>runtime_prelude</code>, with output modes <code>esm</code>, <code>commonjs</code> and <code>inline</code>.</li><li><strong>Value lowering</strong> maps Handl primitives to JS, <code>Arr</code>/<code>Obj</code> to arrays/objects, <code>Bytes</code> to <code>Uint8Array</code>, <code>Handle</code> to an opaque reference, <code>Pair</code>/<code>Either</code> to tagged shapes, and arrows to closures.</li><li><strong>Foreign calls lower to <code>js.call(...)</code></strong> and inline to the native call when the object/method/descriptors are known at compile time; <code>--no-inline-foreign</code> keeps the runtime shim for dynamic calls.</li><li><strong>v1 emits no source maps</strong>; <code># sourceURL</code> may be added in <code>esm</code>/<code>inline</code> modes for debugging.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Compilation was target-specific code in the host, and emitters were mistaken for a compiler. A <code>Compiler</code> trait with per-target plugins makes a target a crate, keeps emitters at the data layer, and lets the CLI dispatch by name.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Compile in the host</strong> — targets are plugins.</li><li><strong>Use <code>handl-emitters</code> as the compiler</strong> — it emits language data.</li><li><strong>Select by file extension</strong> — the target is explicit.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>A target is a crate implementing <code>Compiler</code>; the CLI stays thin.</li><li>JS output has three modes and optional foreign inlining.</li><li>No source maps in v1 — a debugging cost accepted.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/plugin-compile/</code> — the trait and input.</li><li><code>compile-js/</code>, <code>compile-llvm/</code> — the targets.</li><li><code>host-cli</code> — the <code>compile</code> subcommand.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The trait, JS API, output modes, lowering table and inlining rules: +<a href="./../design/0114-handl-compile-plugin-architecture.html"><code>design/0114-handl-compile-plugin-architecture.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};